#!/usr/bin/env python3
"""
pine_export.py
===============
Converts a selected_strategy_config_<SYMBOL>.json (produced by
run_grid_backtest.py) into a Pine Script v5 strategy with the SAME entry/exit
logic, so the exact combo that won the Python grid backtest is what runs on
TradingView / feeds your webhook-to-Delta pipeline -- not a re-typed
approximation.

Usage:
    python pine_export.py outputs/selected_strategy_config_BTCUSDT.json > BTCUSDT_hermes.pine
"""

import json
import sys


TEMPLATE = """\
//@version=5
// Auto-generated by Hermes pine_export.py from config_hash={config_hash}
// Symbol: {symbol}  Timeframe: {timeframe}  Strategy: {strategy_version}
// Source of truth is the Python config, not this file -- regenerate on any
// backtest re-run so live/paper never drifts from the winning grid combo.
strategy("Hermes {symbol} {timeframe} [{config_hash}]", overlay=true,
     default_qty_type=strategy.percent_of_equity, default_qty_value=100,
     commission_type=strategy.commission.percent, commission_value={commission_pct_100})

emaFastLen   = {ema_fast}
emaSlowLen   = {ema_slow}
rsiLen       = {rsi_period}
rsiBuyLevel  = {rsi_buy}
rsiSellLevel = {rsi_sell}
atrLen       = {atr_period}
stopAtrMult  = {stop_atr}
targetAtrMult = {target_atr}
cooldownBars = {cooldown_bars}
allowShort   = {allow_short}

emaFast = ta.ema(close, emaFastLen)
emaSlow = ta.ema(close, emaSlowLen)
rsiVal  = ta.rsi(close, rsiLen)
atrVal  = ta.atr(atrLen)

var int barsSinceExit = 999999
cooldownOver = barsSinceExit >= cooldownBars

longCond  = ta.crossover(emaFast, emaSlow) and rsiVal > rsiBuyLevel and cooldownOver and strategy.position_size == 0
shortCond = allowShort and ta.crossunder(emaFast, emaSlow) and rsiVal < rsiSellLevel and cooldownOver and strategy.position_size == 0

// Entries fill at next bar open by default (process_orders_on_close = false),
// matching the Python engine's "signal at close -> fill at next open" rule.
if longCond
    strategy.entry("Long", strategy.long)
if shortCond
    strategy.entry("Short", strategy.short)

// ATR stop/target set from the ATR value at the bar the signal fired on,
// mirroring the Python engine (stop_atr / target_atr applied to entry fill).
if strategy.position_size > 0
    stopPrice = strategy.position_avg_price - stopAtrMult * atrVal
    targetPrice = strategy.position_avg_price + targetAtrMult * atrVal
    strategy.exit("LongExit", "Long", stop=stopPrice, limit=targetPrice)
if strategy.position_size < 0
    stopPrice = strategy.position_avg_price + stopAtrMult * atrVal
    targetPrice = strategy.position_avg_price - targetAtrMult * atrVal
    strategy.exit("ShortExit", "Short", stop=stopPrice, limit=targetPrice)

if strategy.position_size == 0 and strategy.position_size[1] != 0
    barsSinceExit := 0
else
    barsSinceExit := barsSinceExit + 1
"""


def main():
    if len(sys.argv) != 2:
        print(__doc__)
        sys.exit(1)
    with open(sys.argv[1]) as f:
        cfg = json.load(f)
    p = cfg["parameters"]
    out = TEMPLATE.format(
        config_hash=cfg["config_hash"], symbol=cfg["symbol"], timeframe=cfg["timeframe"],
        strategy_version=cfg["strategy_version"],
        commission_pct_100=cfg["cost_model"].get("commission_pct", 0.0004) * 100,
        ema_fast=p["ema_fast"], ema_slow=p["ema_slow"], rsi_period=p["rsi_period"],
        rsi_buy=p["rsi_buy"], rsi_sell=p["rsi_sell"], atr_period=p["atr_period"],
        stop_atr=p["stop_atr"], target_atr=p["target_atr"], cooldown_bars=p["cooldown_bars"],
        allow_short=str(cfg["risk"].get("allow_short", True)).lower(),
    )
    print(out)


if __name__ == "__main__":
    main()
